    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []

    # Locate the solid 3x3 colored centers of the tiles.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color and all(grid[y][x] == color
                             for y in range(r - 1, r + 2)
                             for x in range(c - 1, c + 2)):
                blocks.append((color, r, c))

    if not blocks:
        return out

    counts = {}
    for color, _, _ in blocks:
        counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    # A non-background tile sends a short ray toward the adjacent tile
    # in each cardinal direction. Only blank separator cells are changed.
    for color, r, c in blocks:
        if color == background:
            continue
        for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            candidates = []
            for color2, r2, c2 in blocks:
                if dr == 0 and r2 == r and (c2 - c) * dc > 0:
                    candidates.append((abs(c2 - c), r2, c2))
                elif dc == 0 and c2 == c and (r2 - r) * dr > 0:
                    candidates.append((abs(r2 - r), r2, c2))
            if candidates:
                _, r2, c2 = min(candidates)
                y, x = r + dr, c + dc
                while (y, x) != (r2, c2):
                    if grid[y][x] == 0:
                        out[y][x] = color
                    y += dr
                    x += dc
    return out
